1	//! `callisto init`: report detected facts, ask only for intent, preview the first release, then write.
2	
3	use std::io::Write;
4	use std::process::ExitCode;
5	
6	use callisto_graph::commands::init::{
7	    self as scaffold, changesets, BinaryRelease, InitAnswers, InitFacts, InitPackage, Versioning,
8	};
9	use callisto_graph::locate::{IgnoreWalkLocator, LocateError};
10	use callisto_graph::GraphError;
11	use callisto_model::{ApplyPermit, BranchName, CommandRunner, InitReport, SCHEMA_VERSION};
12	use dialoguer::{Confirm, Input, Select};
13	
14	use crate::cli::{GlobalArgs, InitArgs, InitVersioning, OutputFormat};
15	use crate::error::CliError;
16	use crate::output::emit_report;
17	use crate::render;
18	use crate::runner::CliCommandRunner;
19	use crate::tty;
20	use crate::workspace::workspace_root;
21	
22	pub const VERSIONING_PROMPT: &str = "How should packages be versioned?";
23	pub const SHIP_PROMPT: &str = "Ship binaries as GitHub release assets?";
24	pub const PRODUCT_PROMPT: &str = "Which package is the product whose binaries ship?";
25	pub const TARGETS_PROMPT: &str = "Artifact target triples (comma-separated)";
26	pub const WRITE_PROMPT: &str = "Write callisto.toml?";
27	pub const WORKFLOW_PROMPT: &str = "Generate a GitHub Actions release workflow?";
28	/// Printed instead of the preview when the repository has no commit to plan from.
29	pub const NO_COMMITS: &str =
30	    "No commits yet: commit, then run `callisto release --dry-run` to preview the first release.";
31	/// Printed instead of asking `WORKFLOW_PROMPT` for a workspace no generated workflow covers.
32	fn workflow_unsupported_note(reason: scaffold::WorkflowUnsupported) -> String {
33	    format!("Skipping GitHub Actions workflow generation: {reason}.")
34	}
35	/// Printed once a generated workflow is written: a merge to `branch` is the release approval.
36	fn merge_publishes_note(branch: &BranchName) -> String {
37	    format!(
38	        "Merging to `{branch}` publishes: require pull requests and reviews on `{branch}` (GitHub → Settings → Rules)."
39	    )
40	}
41	/// Printed once a generated workflow is written: what to do before the first release.
42	fn next_steps_note(secrets: &[&str]) -> String {
43	    let secrets = if secrets.is_empty() {
44	        String::new()
45	    } else {
46	        format!(
47	            "\n  - Add the repository secrets {} (GitHub → Settings → Secrets and variables → Actions).",
48	            secrets.join(", ")
49	        )
50	    };
51	    format!(
52	        "\nNext steps:{secrets}\n  - Describe a change with `callisto add`, then commit.\n  - Preview the first release with `callisto release --dry-run`.\n  - A new package's first publish needs a token that can create it: see {FIRST_PUBLISH_URL}."
53	    )
54	}
55	/// Where the registry-by-registry first-publish guidance lives.
56	const FIRST_PUBLISH_URL: &str = "https://github.com/orin-dx/callisto/blob/main/docs/publishing.md#first-publish";
57	const VERSIONING_CHOICES: [&str; 2] = [
58	    "independent: each package has its own version",
59	    "fixed: every package shares one version",
60	];
61	
62	/// Asks the operator questions; a scripted implementation drives tests.
63	pub trait Prompter {
64	    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError>;
65	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
66	    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError>;
67	}
68	
69	struct TerminalPrompter;
70	
71	impl Prompter for TerminalPrompter {
72	    fn select(&mut self, prompt: &str, items: &[String]) -> Result<usize, CliError> {
73	        Ok(Select::new().with_prompt(prompt).items(items).default(0).interact()?)
74	    }
75	
76	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
77	        Ok(Confirm::new().with_prompt(prompt).default(default).interact()?)
78	    }
79	
80	    fn input(&mut self, prompt: &str, default: Option<&str>) -> Result<String, CliError> {
81	        let mut input = Input::<String>::new().with_prompt(prompt);
82	        if let Some(default) = default {
83	            input = input.default(default.to_owned());
84	        }
85	        Ok(input.interact_text()?)
86	    }
87	}
88	
89	pub fn handle(args: InitArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
90	    run(
91	        args,
92	        global,
93	        tty::is_interactive(),
94	        &mut TerminalPrompter,
95	        &mut std::io::stdout(),
96	        &mut std::io::stderr(),
97	        &CliCommandRunner,
98	    )
99	}
100	
101	/// `init` against explicit terminal state, prompter, output streams, and command runner.
102	pub fn run<'a, R: CommandRunner>(
103	    args: InitArgs,
104	    global: &GlobalArgs,
105	    interactive: bool,
106	    prompter: &mut dyn Prompter,
107	    out: &'a mut dyn Write,
108	    err: &'a mut dyn Write,
109	    runner: &R,
110	) -> Result<ExitCode, CliError> {
111	    validate_flags(&args)?;
112	    // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
113	    let (root, no_root) = match workspace_root(global, runner) {
114	        Ok(root) => (root, None),
115	        Err(CliError::Locate(LocateError::WorkspaceRootNotFound { start, toplevel })) => (
116	            toplevel.clone(),
117	            Some(LocateError::WorkspaceRootNotFound { start, toplevel }),
118	        ),
119	        Err(error) => return Err(error),
120	    };
121	    let locator = IgnoreWalkLocator::new(&root);
122	    if args.workflow && scaffold::is_initialized(&root)? {
123	        // Answers feed callisto.toml, which stays as it is: refuse them rather than drop them.
124	        // The forge and product flags already require an artifact target.
125	        if args.versioning.is_some() || !args.artifact_targets.is_empty() {
126	            return Err(GraphError::InitAlreadyInitialized {
127	                path: root.join("callisto.toml"),
128	            }
129	            .into());
130	        }
131	        return run_workflow_only(&root, &locator, global, out, err, runner);
132	    }
133	    let facts = scaffold::detect(&root, &locator, runner)?;
134	    if let Some(error) = no_root.filter(|_| facts.packages.is_empty()) {
135	        return Err(error.into());
136	    }
137	    let json = global.format == OutputFormat::Json;
138	    // JSON keeps stdout for the report.
139	    macro_rules! human {
140	        () => {
141	            if json {
142	                &mut *err
143	            } else {
144	                &mut *out
145	            }
146	        };
147	    }
148	    write_facts(&facts, human!())?;
149	
150	    if facts.origin.is_none() {
151	        if args.workflow {
152	            return Err(CliError::InitFlagRequiresOrigin {
153	                flag: "workflow",
154	                not_hosted: facts.origin_not_hosted,
155	            });
156	        }
157	        if !args.artifact_targets.is_empty() {
158	            return Err(CliError::InitFlagRequiresOrigin {
159	                flag: "artifact-target",
160	                not_hosted: facts.origin_not_hosted,
161	            });
162	        }
163	    }
164	    if !interactive && !args.yes {
165	        let mut missing = vec!["--yes"];
166	        missing.extend(missing_flags(&args, &facts));
167	        return Err(CliError::InitRequiresYes { missing });
168	    }
169	    if args.yes {
170	        let missing = missing_flags(&args, &facts);
171	        if !missing.is_empty() {
172	            return Err(CliError::InitMissingFlags { missing });
173	        }
174	    }
175	    let prompting = interactive && !args.yes;
176	    let migration = changesets::migrate(&facts.root, &facts);
177	    // A dry run writes nothing, so it previews with the warning instead.
178	    if !migration.public_scoped.is_empty() && !args.yes && !global.dry_run {
179	        return Err(CliError::InitChangesetsAccess {
180	            packages: migration.public_scoped,
181	        });
182	    }
183	    let mut answers = collect_answers(&args, &facts, prompting, prompter)?;
184	
185	    let mut diagnostics = migration.diagnostics.clone();
186	    diagnostics.extend(migration.apply_fixed_groups(&mut answers));
187	    if facts.origin.is_none() {
188	        diagnostics.push(callisto_model::Diagnostic {
189	            code: callisto_model::DiagnosticCode::InitOriginMissing,
190	            severity: callisto_model::DiagnosticSeverity::Warning,
191	            message: if facts.origin_not_hosted {
192	                ORIGIN_NOT_HOSTED_NOTE
193	            } else {
194	                ORIGIN_MISSING_NOTE
195	            }
196	            .to_owned(),
197	            package: None,
198	            path: None,
199	            escalated_by: None,
200	            governed_by: None,
201	        });
202	    }
203	    let shape = match scaffold::workflow_shape(&facts, answers.binaries.is_some()) {
204	        Err(reason) if args.workflow => {
205	            return Err(GraphError::InitWorkflowUnsupported {
206	                reason: reason.to_string(),
207	            }
208	            .into());
209	        }
210	        Err(reason) => {
211	            let note = workflow_unsupported_note(reason);
212	            diagnostics.push(callisto_model::Diagnostic {
213	                code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
214	                severity: callisto_model::DiagnosticSeverity::Warning,
215	                message: note,
216	                package: None,
217	                path: None,
218	                escalated_by: None,
219	                governed_by: None,
220	            });
221	            None
222	        }
223	        Ok(shape) => Some(shape),
224	    };
225	    let want_workflow = match shape {
226	        None => false,
227	        Some(_) if args.workflow => true,
228	        Some(_) if args.no_workflow => false,
229	        Some(_) if prompting && facts.origin.is_some() => prompter.confirm(WORKFLOW_PROMPT, true)?,
230	        // The workflow is GitHub Actions, so only a GitHub origin gets it unasked.
231	        Some(_) => facts.origin_repository.is_some(),
232	    };
233	    // A workflow nobody asked for (the default) never fails `init`: if it cannot be built, say why and go on.
234	    let asked_for_workflow = args.workflow || prompting;
235	    let workflow = match shape.filter(|_| want_workflow) {
236	        Some(shape) => match build_workflow(&facts, shape, migration.base_branch.as_ref(), runner, human!()) {
237	            Ok(built) => Some(built),
238	            Err(error) if !asked_for_workflow => {
239	                let note =
240	                    format!("Skipping the GitHub Actions workflow: {error}. Run `callisto init --workflow` to retry.");
241	                diagnostics.push(callisto_model::Diagnostic {
242	                    code: callisto_model::DiagnosticCode::WorkflowGenerationUnsupported,
243	                    severity: callisto_model::DiagnosticSeverity::Warning,
244	                    message: note,
245	                    package: None,
246	                    path: None,
247	                    escalated_by: None,
248	                    governed_by: None,
249	                });
250	                None
251	            }
252	            Err(error) => return Err(error),
253	        },
254	        None => None,
255	    };
256	    if workflow.is_none() {
257	        diagnostics.extend(migration.base_branch_unused());
258	    }
259	
260	    let config = scaffold::render_config(&facts, &answers);
261	    let plan = if facts.has_commit {
262	        Some(scaffold::preview(&facts, &config, &locator, runner)?)
263	    } else {
264	        None
265	    };
266	    if config
267	        .lines()
268	        .all(|line| line.trim().is_empty() || line.trim_start().starts_with('#'))
269	    {
270	        writeln!(human!(), "\ncallisto.toml: no settings needed, the defaults apply.")?;
271	    } else {
272	        writeln!(human!(), "\ncallisto.toml:\n{config}")?;
273	    }
274	    match plan {
275	        Some((plan, pending)) => {
276	            writeln!(human!(), "First release preview (`callisto release --dry-run`):")?;
277	            super::release::write_release_preview(plan.as_ref(), OutputFormat::Text, human!())?;
278	            // `origin` already has its own note above, so an unbound tag adds nothing.
279	            if let Some(plan) = &plan {
280	                diagnostics.extend(plan.diagnostics.clone());
281	            }
282	            diagnostics.extend(super::release::pending_version_diagnostic(&pending));
283	        }
284	        None => writeln!(human!(), "{NO_COMMITS}")?,
285	    }
286	    if let Some((_, branch)) = &workflow {
287	        writeln!(human!(), "\n{}", workflow_summary(&facts.root, branch))?;
288	    }
289	
290	    // Computed before any write, so the `.changeset/README.md` existence check sees disk state as-is.
291	    let files = scaffold::init_files(&facts.root, workflow.is_some())?;
292	    let mut report = if global.dry_run {
293	        InitReport {
294	            schema_version: SCHEMA_VERSION,
295	            initialized: false,
296	            config_path: facts.root.join("callisto.toml"),
297	            config,
298	            files,
299	            diagnostics: Vec::new(),
300	        }
301	    } else {
302	        if prompting {
303	            // Said before the question so a decline keeps them; `finish` must not repeat them.
304	            if !json {
305	                render::render_diagnostics(&diagnostics, None, &mut &mut *err)?;
306	                diagnostics.clear();
307	            }
308	            if !prompter.confirm(WRITE_PROMPT, true)? {
309	                writeln!(human!(), "Initialization cancelled; nothing was written.")?;
310	                return Ok(ExitCode::SUCCESS);
311	            }
312	        }
313	        let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
314	        let mut report = scaffold::write(&facts.root, &config, &permit)?;
315	        if let Some((workflow, branch)) = &workflow {
316	            scaffold::write_workflow(&facts.root, workflow, &permit)?;
317	            diagnostics.push(announce_workflow(human!(), &facts, branch)?);
318	        }
319	        report.files = files;
320	        report
321	    };
322	    report.diagnostics.extend(diagnostics);
323	    finish(&report, global, out, err)
324	}
325	
326	/// The one emitter for `init`'s notes and advice: stderr once in every format, and the JSON report carries them too.
327	fn finish(
328	    report: &InitReport,
329	    global: &GlobalArgs,
330	    out: &mut dyn Write,
331	    err: &mut dyn Write,
332	) -> Result<ExitCode, CliError> {
333	    render::render_diagnostics(&report.diagnostics, None, &mut &mut *err)?;
334	    if global.format == OutputFormat::Json {
335	        emit_report(&mut &mut *out, report, global.dry_run)?;
336	    } else {
337	        render::render_init(report, &mut &mut *out)?;
338	    }
339	    Ok(ExitCode::SUCCESS)
340	}
341	
342	/// The workflow's path and what it does, in place of its text.
343	fn workflow_summary(root: &std::path::Path, branch: &BranchName) -> String {
344	    format!(
345	        "{}: on each push to `{branch}`, opens a release PR while version work is pending and publishes once it merges.",
346	        scaffold::workflow_path(root).display()
347	    )
348	}
349	
350	/// Prints what a written workflow means and what to do next; the same text is recorded as a diagnostic.
351	fn announce_workflow(
352	    human: &mut dyn Write,
353	    facts: &InitFacts,
354	    branch: &BranchName,
355	) -> Result<callisto_model::Diagnostic, CliError> {
356	    let note = merge_publishes_note(branch);
357	    writeln!(human, "{}", next_steps_note(&scaffold::registry_secret_names(facts)))?;
358	    Ok(callisto_model::Diagnostic {
359	        code: callisto_model::DiagnosticCode::WorkflowMergePublishes,
360	        severity: callisto_model::DiagnosticSeverity::Info,
361	        message: note,
362	        package: None,
363	        path: None,
364	        escalated_by: None,
365	        governed_by: None,
366	    })
367	}
368	
369	/// `init --workflow` in a workspace that already has `callisto.toml`: writes only the workflow.
370	fn run_workflow_only<R: CommandRunner>(
371	    root: &std::path::Path,
372	    locator: &IgnoreWalkLocator,
373	    global: &GlobalArgs,
374	    out: &mut dyn Write,
375	    err: &mut dyn Write,
376	    runner: &R,
377	) -> Result<ExitCode, CliError> {
378	    let facts = scaffold::detect_initialized(root, locator, runner)?;
379	    let json = global.format == OutputFormat::Json;
380	    let human: &mut dyn Write = if json { &mut *err } else { &mut *out };
381	    write_facts(&facts, human)?;
382	    if facts.origin.is_none() {
383	        return Err(CliError::InitFlagRequiresOrigin {
384	            flag: "workflow",
385	            not_hosted: facts.origin_not_hosted,
386	        });
387	    }
388	    let shape =
389	        scaffold::workflow_shape(&facts, scaffold::existing_config_ships_binaries(&facts.root)?).map_err(|reason| {
390	            GraphError::InitWorkflowUnsupported {
391	                reason: reason.to_string(),
392	            }
393	        })?;
394	    let base_branch = changesets::base_branch(root);
395	    let (workflow, branch) = build_workflow(&facts, shape, base_branch.as_ref(), runner, human)?;
396	    writeln!(human, "\n{}", workflow_summary(&facts.root, &branch))?;
397	    let mut diagnostics = Vec::new();
398	    if !global.dry_run {
399	        let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
400	        scaffold::write_workflow(&facts.root, &workflow, &permit)?;
401	        diagnostics.push(announce_workflow(human, &facts, &branch)?);
402	    }
403	    let config_path = facts.root.join("callisto.toml");
404	    let config = callisto_model::strict_fs::read_optional(&config_path)
405	        .map_err(|error| GraphError::InitIo {
406	            path: config_path.clone(),
407	            message: error.to_string(),
408	        })?
409	        .unwrap_or_default();
410	    let report = InitReport {
411	        schema_version: SCHEMA_VERSION,
412	        initialized: !global.dry_run,
413	        config_path,
414	        config,
415	        files: vec![scaffold::workflow_path(&facts.root)],
416	        diagnostics,
417	    };
418	    finish(&report, global, out, err)
419	}
420	
421	/// The workflow text and the default branch it triggers on.
422	fn build_workflow<R: CommandRunner>(
423	    facts: &InitFacts,
424	    shape: scaffold::WorkflowShape,
425	    base_branch: Option<&BranchName>,
426	    runner: &R,
427	    human: &mut dyn Write,
428	) -> Result<(String, BranchName), CliError> {
429	    scaffold::ensure_workflow_absent(&facts.root)?;
430	    let branch = match base_branch {
431	        Some(name) => scaffold::DefaultBranch {
432	            name: name.clone(),
433	            source: scaffold::DefaultBranchSource::ChangesetsBaseBranch,
434	        },
435	        None => scaffold::default_branch(runner, &facts.root),
436	    };
437	    writeln!(human, "  default branch: {} (from {})", branch.name, branch.source)?;
438	    let version = semver::Version::parse(env!("CARGO_PKG_VERSION")).expect("Cargo package versions are semver");
439	    let commit = scaffold::resolve_release_commit(runner, &facts.root, &version)?;
440	    let content = scaffold::render_workflow(facts, shape, &branch.name, &commit, &version);
441	    Ok((content, branch.name))
442	}
443	
444	/// Printed, and recorded as a warning diagnostic, when no `origin` remote is configured.
445	const ORIGIN_MISSING_NOTE: &str = "No `origin` remote is configured: skipping the release workflow and \
446	shipping-binaries questions; `callisto release` will refuse until one is added.";
447	
448	/// Printed, and recorded as a warning diagnostic, when `origin` is not a hosted remote; the value is never shown.
449	const ORIGIN_NOT_HOSTED_NOTE: &str = "`origin` is not a hosted remote (use https://, ssh:// or git@host:owner/repo): \
450	skipping the release workflow and shipping-binaries questions; `callisto release` will refuse until one is set.";
451	
452	/// Rejects flag combinations invalid regardless of workspace facts.
453	fn validate_flags(args: &InitArgs) -> Result<(), CliError> {
454	    if args.workflow && args.no_workflow {
455	        return Err(CliError::InitWorkflowFlagsConflict);
456	    }
457	    if args.artifact_targets.is_empty() && args.product_package.is_some() {
458	        return Err(CliError::InitFlagRequiresArtifactTarget {
459	            flag: "product-package",
460	        });
461	    }
462	    Ok(())
463	}
464	
465	fn write_facts(facts: &InitFacts, out: &mut dyn Write) -> Result<(), CliError> {
466	    let ecosystems: Vec<&str> = facts.ecosystems.iter().map(|ecosystem| ecosystem.prefix()).collect();
467	    writeln!(out, "Detected:")?;
468	    writeln!(out, "  ecosystems: {}", ecosystems.join(", "))?;
469	    let origin = match (&facts.origin, facts.origin_not_hosted) {
470	        (Some(origin), _) => origin.as_str(),
471	        (None, true) => "not hosted",
472	        (None, false) => "none",
473	    };
474	    writeln!(out, "  origin: {origin}")?;
475	    writeln!(out, "  packages:")?;
476	    for package in &facts.packages {
477	        let tag = package.last_tag.as_ref().map_or("none", |tag| tag.as_str());
478	        write!(out, "    {} {} (last tag: {tag}", package.id, package.version)?;
479	        if package.is_binary() {
480	            write!(out, "; binary: {}", package.bin_names.join(", "))?;
481	        }
482	        writeln!(out, ")")?;
483	    }
484	    Ok(())
485	}
486	
487	/// Flags `--yes` needs that were not supplied.
488	fn missing_flags(args: &InitArgs, facts: &InitFacts) -> Vec<&'static str> {
489	    let mut missing = Vec::new();
490	    if !args.artifact_targets.is_empty()
491	        && facts.binary_packages().next().is_some()
492	        && args.product_package.is_none()
493	        && facts.binary_packages().nth(1).is_some()
494	    {
495	        missing.push("--product-package");
496	    }
497	    missing
498	}
499	
500	fn missing(flag: &'static str) -> CliError {
501	    CliError::InitMissingFlags { missing: vec![flag] }
502	}
503	
504	fn collect_answers(
505	    args: &InitArgs,
506	    facts: &InitFacts,
507	    prompting: bool,
508	    prompter: &mut dyn Prompter,
509	) -> Result<InitAnswers, CliError> {
510	    let versioning = match args.versioning {
511	        Some(InitVersioning::Fixed) => Versioning::Fixed,
512	        Some(InitVersioning::Independent) => Versioning::Independent,
513	        // Fixed and independent mean the same for one package, so only several packages are asked.
514	        None if prompting && facts.packages.len() > 1 => {
515	            let choices: Vec<String> = VERSIONING_CHOICES.iter().map(|choice| (*choice).to_owned()).collect();
516	            match prompter.select(VERSIONING_PROMPT, &choices)? {
517	                0 => Versioning::Independent,
518	                _ => Versioning::Fixed,
519	            }
520	        }
521	        None => Versioning::Independent,
522	    };
523	    let no_binaries = InitAnswers {
524	        versioning,
525	        binaries: None,
526	        fixed_groups: Vec::new(),
527	    };
528	
529	    let binaries: Vec<&InitPackage> = facts.binary_packages().collect();
530	    if binaries.is_empty() && !args.artifact_targets.is_empty() {
531	        if let Some(package) = facts.unsupported_artifact_packages().next() {
532	            return Err(GraphError::InitUnsupportedArtifactBuilder {
533	                package: package.id.clone(),
534	                ecosystem: package
535	                    .id
536	                    .split_once('/')
537	                    .map_or("unknown", |(ecosystem, _)| ecosystem)
538	                    .to_owned(),
539	            }
540	            .into());
541	        }
542	        return Err(GraphError::InitNoBinaryPackage.into());
543	    }
544	    let requested_product = args
545	        .product_package
546	        .as_deref()
547	        .map(|name| facts.product_package(name))
548	        .transpose()?;
549	    if binaries.is_empty() {
550	        return Ok(no_binaries);
551	    }
552	    // No `origin`: the forge question below has nothing to validate a repository against, so
553	    // shipping is never offered (skips straight to `no_binaries`); `--artifact-target` without
554	    // `origin` is already rejected up front in `run`.
555	    let ship = !args.artifact_targets.is_empty()
556	        || (facts.origin.is_some() && prompting && prompter.confirm(SHIP_PROMPT, false)?);
557	    if !ship {
558	        return Ok(no_binaries);
559	    }
560	    // A release goes to origin's GitHub repository, so shipping needs one.
561	    if facts.origin_repository.is_none() {
562	        return Err(GraphError::ReleaseForgeRepositoryMissing.into());
563	    }
564	
565	    let product = match (requested_product, binaries.as_slice()) {
566	        (Some(product), _) => product,
567	        (None, [only]) => only,
568	        (None, _) if prompting => {
569	            let ids: Vec<String> = binaries.iter().map(|package| package.id.clone()).collect();
570	            binaries[prompter.select(PRODUCT_PROMPT, &ids)?]
571	        }
572	        (None, _) => return Err(missing("--product-package")),
573	    };
574	
575	    let targets = if args.artifact_targets.is_empty() {
576	        loop {
577	            let answer = prompter.input(TARGETS_PROMPT, None)?;
578	            let targets: Vec<String> = answer.split(',').map(str::trim).map(str::to_owned).collect();
579	            if targets.iter().all(|target| target.is_empty()) {
580	                // Nothing meaningful submitted: re-ask rather than error.
581	                continue;
582	            }
583	            break targets;
584	        }
585	    } else {
586	        args.artifact_targets.clone()
587	    };
588	    let targets = scaffold::validate_targets(&targets)?;
589	
590	    Ok(InitAnswers {
591	        versioning,
592	        binaries: Some(BinaryRelease {
593	            product: product.id.clone(),
594	            targets,
595	        }),
596	        fixed_groups: Vec::new(),
597	    })
598	}
599	
600	#[cfg(test)]
601	mod tests;
